public:
    void nextPermutation(vector<int>& nums) {
        int p1 = -1, p2 = -1;
        for (int i = nums.size() - 1; i >= 1; i--) {
            if (nums[i] > nums[i - 1]) {
                p1 = i - 1;
                break;
            }
        }
        if (p1 == -1) {
            reverse(nums, 0);
            return;
        }
        for (int i = nums.size() - 1; i > p1; i--) {
            if (nums[i] > nums[p1]) {
                p2 = i;
                break;
            }
        }
        swap(nums, p1, p2);
        reverse(nums, p1 + 1);
        return;
    }

    void reverse(vector<int>& nums, int start) {
        int p1 = start, p2 = nums.size() - 1;
        while (p1 < p2) {
            swap(nums, p1, p2);
            p1++;
            p2--;
        }
    }

    void swap(vector<int>& nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
};

